function localizationTable = localizeMovie(frames, photonEvents, ...
        photophysics, trajectories, detector, opts)
    import membrane_tracking.fluctuating_miet.*

    nFrames = size(frames, 2);
    columns = {'frame','timeS','xUm','yUm','signalPhotons', ...
        'backgroundPerChannel','reducedPoissonDeviance','crbVarXUm2', ...
        'crbVarYUm2','crbCovXYUm2','lifetimeNs','lifetimeSigmaNs', ...
        'heightUm','heightSigmaUm','nPhotonsForLifetime', ...
        'trueBrightMoleculeCount','nearestTrueMolecule', ...
        'truthPositionErrorUm','trueXUm','trueYUm','trueZUm', ...
        'trueLifetimeNs','trueFieldHeightUm'};
    store = zeros(nFrames, numel(columns));
    nAccepted = 0;

    for frame = 1:nFrames
        data = double(frames(:,frame));
        if sum(data) - detector.nChannels * detector.backgroundMeanCounts ...
                < opts.minPhotonsPerLocalization
            continue;
        end
        [model, fisher, ok] = fitSingleEmitterISM(data, detector, opts);
        if ~ok || model.reducedPoissonDeviance > opts.maxReducedPoissonDeviance
            continue;
        end
        firstRow = photophysics.eventStartRow(frame);
        lastRow = photophysics.eventEndRow(frame);
        if firstRow <= 0 || lastRow < firstRow
            continue;
        end
        rows = firstRow:lastRow;
        [tauHat, tauSigma, lifetimeOk] = fitFrameLifetime( ...
            photonEvents.microtimeNs(rows), ...
            photonEvents.detectorChannel(rows), model, detector, opts);
        if ~lifetimeOk
            continue;
        end
        truthXY = trajectories.positionsXYUm(:,:,frame);
        delta = truthXY - [model.xUm model.yUm];
        [truthError, nearest] = min(hypot(delta(:,1), delta(:,2)));

        nAccepted = nAccepted + 1;
        store(nAccepted,:) = [frame, (frame-1)*opts.dtS, model.xUm, ...
            model.yUm, model.amplitude, model.background, ...
            model.reducedPoissonDeviance, fisher.covarianceXY(1,1), ...
            fisher.covarianceXY(2,2), fisher.covarianceXY(1,2), ...
            tauHat, tauSigma, ...
            (tauHat - opts.lifetimeAtSubstrateNs)/opts.lifetimeSlopeNsPerUm, ...
            tauSigma/opts.lifetimeSlopeNsPerUm, numel(rows), ...
            photophysics.brightMoleculeCountPerFrame(frame), nearest, ...
            truthError, truthXY(nearest,1), truthXY(nearest,2), ...
            trajectories.positionsZUm(nearest,frame), ...
            trajectories.lifetimeNs(nearest,frame), ...
            trajectories.fieldHeightUm(nearest,frame)];
    end

    localizationTable = array2table(store(1:nAccepted,:), ...
        'VariableNames', columns);
end
